int n;
vector<bool> cols, diag, anti;        // diag idx: r-c+n, anti idx: r+c

int solve(int row) {
    if (row == n) return 1;
    int count = 0;
    for (int c = 0; c < n; ++c) {
        if (cols[c] || diag[row - c + n] || anti[row + c]) continue;
        cols[c] = diag[row - c + n] = anti[row + c] = true;
        count += solve(row + 1);
        cols[c] = diag[row - c + n] = anti[row + c] = false;   // backtrack
    }
    return count;
}

def total_n_queens(n):
    cols, diag, anti = set(), set(), set()
    def solve(row):
        if row == n: return 1
        count = 0
        for c in range(n):
            if c in cols or (row-c) in diag or (row+c) in anti:
                continue
            cols.add(c); diag.add(row-c); anti.add(row+c)
            count += solve(row + 1)
            cols.remove(c); diag.remove(row-c); anti.remove(row+c)
        return count
    return solve(0)

class Solution {
    int n; vector<vector<string>> res; vector<int> pos;
    set<int> cols, d1, d2;
    void solve(int r) {
        if (r == n) {
            vector<string> board(n, string(n, '.'));
            for (int i = 0; i < n; i++) board[i][pos[i]] = 'Q';
            res.push_back(board); return;
        }
        for (int c = 0; c < n; c++) {
            if (cols.count(c) || d1.count(r - c) || d2.count(r + c)) continue;
            cols.insert(c); d1.insert(r - c); d2.insert(r + c); pos[r] = c;
            solve(r + 1);
            cols.erase(c); d1.erase(r - c); d2.erase(r + c);
        }
    }
public:
    vector<vector<string>> solveNQueens(int N) { n = N; pos.assign(n, 0); solve(0); return res; }
};

class Solution:
    def solveNQueens(self, n: int) -> list[list[str]]:
        res = []
        cols, d1, d2 = set(), set(), set()
        pos = [0] * n
        def solve(r):
            if r == n:
                res.append(["".join('Q' if pos[i] == c else '.' for c in range(n)) for i in range(n)])
                return
            for c in range(n):
                if c in cols or (r - c) in d1 or (r + c) in d2:
                    continue
                cols.add(c); d1.add(r - c); d2.add(r + c); pos[r] = c
                solve(r + 1)
                cols.discard(c); d1.discard(r - c); d2.discard(r + c)
        solve(0)
        return res

class Solution {
    int n, count = 0;
    set<int> cols, d1, d2;
    void solve(int r) {
        if (r == n) { count++; return; }
        for (int c = 0; c < n; c++) {
            if (cols.count(c) || d1.count(r - c) || d2.count(r + c)) continue;
            cols.insert(c); d1.insert(r - c); d2.insert(r + c);
            solve(r + 1);
            cols.erase(c); d1.erase(r - c); d2.erase(r + c);
        }
    }
public:
    int totalNQueens(int N) { n = N; solve(0); return count; }
};

class Solution:
    def totalNQueens(self, n: int) -> int:
        self.count = 0
        cols, d1, d2 = set(), set(), set()
        def solve(r):
            if r == n:
                self.count += 1
                return
            for c in range(n):
                if c in cols or (r - c) in d1 or (r + c) in d2:
                    continue
                cols.add(c); d1.add(r - c); d2.add(r + c)
                solve(r + 1)
                cols.discard(c); d1.discard(r - c); d2.discard(r + c)
        solve(0)
        return self.count

class Solution {
    bool valid(vector<vector<char>>& b, int r, int c, char d) {
        for (int i = 0; i < 9; i++) {
            if (b[r][i] == d || b[i][c] == d) return false;
            if (b[3*(r/3) + i/3][3*(c/3) + i%3] == d) return false;
        }
        return true;
    }
    bool solve(vector<vector<char>>& b) {
        for (int r = 0; r < 9; r++)
            for (int c = 0; c < 9; c++)
                if (b[r][c] == '.') {
                    for (char d = '1'; d <= '9'; d++)
                        if (valid(b, r, c, d)) {
                            b[r][c] = d;
                            if (solve(b)) return true;
                            b[r][c] = '.';
                        }
                    return false;
                }
        return true;
    }
public:
    void solveSudoku(vector<vector<char>>& board) { solve(board); }
};

class Solution:
    def solveSudoku(self, board: list[list[str]]) -> None:
        def valid(r, c, d):
            for i in range(9):
                if board[r][i] == d or board[i][c] == d:
                    return False
                if board[3*(r//3) + i//3][3*(c//3) + i%3] == d:
                    return False
            return True
        def solve():
            for r in range(9):
                for c in range(9):
                    if board[r][c] == '.':
                        for d in '123456789':
                            if valid(r, c, d):
                                board[r][c] = d
                                if solve():
                                    return True
                                board[r][c] = '.'
                        return False
            return True
        solve()

class Solution {
    int R, C; string w;
    bool dfs(vector<vector<char>>& b, int r, int c, int k) {
        if (k == (int)w.size()) return true;
        if (r < 0 || c < 0 || r >= R || c >= C || b[r][c] != w[k]) return false;
        char tmp = b[r][c]; b[r][c] = '#';
        bool found = dfs(b, r+1, c, k+1) || dfs(b, r-1, c, k+1) || dfs(b, r, c+1, k+1) || dfs(b, r, c-1, k+1);
        b[r][c] = tmp;
        return found;
    }
public:
    bool exist(vector<vector<char>>& board, string word) {
        R = board.size(); C = board[0].size(); w = word;
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++)
                if (dfs(board, r, c, 0)) return true;
        return false;
    }
};

class Solution:
    def exist(self, board: list[list[str]], word: str) -> bool:
        R, C = len(board), len(board[0])
        def dfs(r, c, k):
            if k == len(word):
                return True
            if r < 0 or c < 0 or r >= R or c >= C or board[r][c] != word[k]:
                return False
            tmp = board[r][c]; board[r][c] = '#'
            found = (dfs(r+1, c, k+1) or dfs(r-1, c, k+1) or
                     dfs(r, c+1, k+1) or dfs(r, c-1, k+1))
            board[r][c] = tmp
            return found
        return any(dfs(r, c, 0) for r in range(R) for c in range(C))

class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (total % k) return false;
        int target = total / k;
        sort(nums.rbegin(), nums.rend());
        if (nums[0] > target) return false;
        vector<int> buckets(k, 0);
        function<bool(int)> dfs = [&](int i) {
            if (i == (int)nums.size()) return true;
            for (int b = 0; b < k; b++) {
                if (buckets[b] + nums[i] <= target) {
                    buckets[b] += nums[i];
                    if (dfs(i + 1)) return true;
                    buckets[b] -= nums[i];
                }
                if (buckets[b] == 0) break;   // prune symmetric empty buckets
            }
            return false;
        };
        return dfs(0);
    }
};

class Solution:
    def canPartitionKSubsets(self, nums: list[int], k: int) -> bool:
        total = sum(nums)
        if total % k:
            return False
        target = total // k
        nums.sort(reverse=True)
        if nums[0] > target:
            return False
        buckets = [0] * k
        def dfs(i):
            if i == len(nums):
                return True
            for b in range(k):
                if buckets[b] + nums[i] <= target:
                    buckets[b] += nums[i]
                    if dfs(i + 1):
                        return True
                    buckets[b] -= nums[i]
                if buckets[b] == 0:
                    break
            return False
        return dfs(0)
